# ---------------------------------------------------------------------------
# Neon gradient border — neon turquoise (#00e5ff) → neon purple (#c800ff)
# Continuous loop around the full perimeter with rounded corners.
# Used on both the splash screen and the main application window.
# ---------------------------------------------------------------------------

import math as _math

# Fixed gradient endpoints (intentionally not theme-dependent)
_NEON_LEFT_HEX  = "#00e5ff"   # neon turquoise
_NEON_RIGHT_HEX = "#c800ff"   # neon purple
_NEON_L = (0x00, 0xe5, 0xff)
_NEON_R = (0xc8, 0x00, 0xff)


def _neon_colour_at(t):
    """Return a hex colour string for position *t* (0.0–1.0) along the perimeter.

    The gradient loops: turquoise at t=0 (top-left), purple at t=0.5
    (bottom-right), back to turquoise at t=1.0.  This gives a symmetric
    left=turquoise, right=purple appearance on both sides.
    """
    # Mirror so second half goes purple→turquoise
    u = t if t <= 0.5 else 1.0 - t
    # Scale 0.0–0.5 → 0.0–1.0
    u2 = u * 2.0
    rl, gl, bl = _NEON_L
    rr, gr, br = _NEON_R
    r = int(rl + (rr - rl) * u2)
    g = int(gl + (gr - gl) * u2)
    b = int(bl + (br - bl) * u2)
    return f"#{r:02x}{g:02x}{b:02x}"


def _draw_neon_rounded_border(canvas, w, h, thickness=6, radius=12, bg="#000000"):
    """Draw a rounded-corner neon gradient border on *canvas*.

    The border is a single closed path traced clockwise around the perimeter.
    Each short segment is coloured according to its position along the total
    perimeter so the gradient flows continuously around all four sides and
    corners.

    Parameters
    ----------
    canvas    : tk.Canvas — must already be sized w×h
    w, h      : int — canvas dimensions in pixels
    thickness : int — stroke width in pixels
    radius    : int — corner arc radius in pixels
    bg        : str — background colour to paint first (clears canvas)
    """
    if w < (radius + thickness) * 2 + 4 or h < (radius + thickness) * 2 + 4:
        return
    canvas.delete("neon_border")

    # Clamp radius so it can never exceed half the shortest side minus thickness
    r = min(radius, (min(w, h) - thickness * 2) // 2)
    if r < 2:
        r = 2

    half = thickness // 2          # inset so stroke stays inside the canvas
    T = half                        # alias

    # ── Build the full perimeter as a list of (x, y) points ──────────────
    # Clockwise from top-left corner arc.
    # Straight segments contribute their pixel length; arc segments are
    # approximated by N_ARC points so each sub-segment is ~2 px.
    N_ARC = max(6, int(_math.pi * r / 2 / 2))   # pts per 90° arc

    points = []   # list of (x, y)

    # Helper: append a 90° arc
    def arc(cx, cy, start_angle_deg, end_angle_deg):
        for i in range(N_ARC + 1):
            a = _math.radians(
                start_angle_deg + (end_angle_deg - start_angle_deg) * i / N_ARC
            )
            points.append((cx + r * _math.cos(a), cy + r * _math.sin(a)))

    # Top-left corner: arc from 180° to 270° (quadrant: x-, y-)
    arc(T + r, T + r,  180, 270)
    # Top edge straight
    points.append((w - T - r, T))
    # Top-right corner: arc from 270° to 0°
    arc(w - T - r, T + r, 270, 360)
    # Right edge straight
    points.append((w - T, h - T - r))
    # Bottom-right corner: arc from 0° to 90°
    arc(w - T - r, h - T - r, 0, 90)
    # Bottom edge straight
    points.append((T + r, h - T))
    # Bottom-left corner: arc from 90° to 180°
    arc(T + r, h - T - r, 90, 180)
    # Left edge straight
    points.append((T, T + r))

    # ── Compute cumulative perimeter distances ────────────────────────────
    dists = [0.0]
    for i in range(1, len(points)):
        dx = points[i][0] - points[i-1][0]
        dy = points[i][1] - points[i-1][1]
        dists.append(dists[-1] + _math.hypot(dx, dy))
    total = dists[-1]
    if total < 1:
        return

    # ── Draw each segment as a coloured line ─────────────────────────────
    for i in range(1, len(points)):
        t_mid = (dists[i-1] + dists[i]) * 0.5 / total
        colour = _neon_colour_at(t_mid)
        x0, y0 = points[i-1]
        x1, y1 = points[i]
        canvas.create_line(
            x0, y0, x1, y1,
            fill=colour, width=thickness,
            capstyle="round", joinstyle="round",
            tags="neon_border",
        )

    # Close the loop — connect last point back to first
    t_mid = (dists[-1] + total) * 0.5 / total % 1.0
    colour = _neon_colour_at(t_mid)
    x0, y0 = points[-1]
    x1, y1 = points[0]
    canvas.create_line(
        x0, y0, x1, y1,
        fill=colour, width=thickness,
        capstyle="round", joinstyle="round",
        tags="neon_border",
    )


class ModelDownloaderWizard:
    def __init__(self, parent, manager):
        self.parent = parent
        self.manager = manager
        
        self.dialog = tk.Toplevel(parent)
        self.dialog.title("Model Manager & Downloader")
        self.dialog.transient(parent)
        self.dialog.grab_set()
        self.dialog.geometry("860x680")
        self.dialog.minsize(760, 520)
        
        self.manager._style_panel(self.dialog, self.manager.colors["bg"])
        
        # Detect VRAM & GPU name
        self.vram_gb = self.manager._detect_gpu_vram_gb()
        _, self.gpu_name = self.manager._detect_gpu_type()
        
        # Perform dynamic audit of all models
        self.reports = self.manager.audit_all_manifest_models()
        
        # Add chatbot models
        self.chatbot_entries = [
            {
                "id": "chatbot_qwen3_7b",
                "workflow": "chatbot",
                "workflow_label": "Chatbot LLM",
                "label": "Qwen3 7B Chatbot (Low VRAM)",
                "filename": "Qwen_Qwen3-7B-Q4_K_M.gguf",
                "dest_subdir": "LLM_Models",
                "download_url": "https://huggingface.co/bartowski/Qwen_Qwen3-7B-GGUF/resolve/main/Qwen_Qwen3-7B-Q4_K_M.gguf?download=true",
                "size_bytes": 4800000000,
                "install_method": "download",
                "sha256": None,
            },
            {
                "id": "chatbot_qwen3_14b",
                "workflow": "chatbot",
                "workflow_label": "Chatbot LLM",
                "label": "Qwen3 14B Chatbot (Standard / High VRAM)",
                "filename": "Qwen_Qwen3-14B-Q4_K_M.gguf",
                "dest_subdir": "LLM_Models",
                "download_url": "https://huggingface.co/bartowski/Qwen_Qwen3-14B-GGUF/resolve/main/Qwen_Qwen3-14B-Q4_K_M.gguf?download=true",
                "size_bytes": 10200000000,
                "install_method": "download",
                "sha256": None,
            }
        ]
        
        for cb in self.chatbot_entries:
            resolved = None
            filename = cb["filename"]
            if self.manager.chatbot_model_root and os.path.exists(os.path.join(self.manager.chatbot_model_root, filename)):
                resolved = os.path.join(self.manager.chatbot_model_root, filename)
            else:
                for cand in self.manager._get_chatbot_model_root_candidates():
                    if os.path.exists(os.path.join(cand, filename)):
                        resolved = os.path.join(cand, filename)
                        break
            cb["resolved_path"] = resolved
            cb["destination_path"] = os.path.join(self.manager.chatbot_model_root or os.path.join(self.manager.app_root_dir, "LLM_Models"), filename)
            cb["source_path"] = None
            cb["source_name"] = "Hugging Face"
            cb["source_page_url"] = "https://huggingface.co/bartowski/Qwen_Qwen3-14B-GGUF"
            
        self.all_entries = self.reports + self.chatbot_entries
        self.selection_vars = {}
        
        self._build_ui()

    def _build_ui(self):
        shell = tk.Frame(self.dialog, padx=18, pady=18)
        shell.pack(fill=tk.BOTH, expand=True)
        self.manager._style_panel(shell, self.manager.colors["bg"])
        
        # Header Info
        header_frame = tk.Frame(shell)
        header_frame.pack(fill=tk.X, pady=(0, 12))
        self.manager._style_panel(header_frame, self.manager.colors["bg"])
        
        title = tk.Label(header_frame, text="Model Manager & Downloader")
        title.pack(anchor="w")
        self.manager._style_label(title, "title", self.manager.colors["bg"])
        
        vram_text = f"GPU Detected: {self.gpu_name} | VRAM: {self.vram_gb:.1f} GB"
        vram_lbl = tk.Label(header_frame, text=vram_text)
        vram_lbl.pack(anchor="w", pady=(2, 4))
        self.manager._style_label(vram_lbl, "muted", self.manager.colors["bg"])
        
        help_desc = "Select the models you want to download. Prompt2MTV has pre-selected the optimal models for your GPU."
        desc_lbl = tk.Label(header_frame, text=help_desc)
        desc_lbl.pack(anchor="w")
        self.manager._style_label(desc_lbl, "body", self.manager.colors["bg"])
        
        # Main Checklist Scrollable Area
        checklist_container = tk.Frame(shell, padx=10, pady=10)
        checklist_container.pack(fill=tk.BOTH, expand=True, pady=(4, 14))
        self.manager._style_panel(checklist_container, self.manager.colors["surface"], border=True)
        
        canvas = tk.Canvas(checklist_container, borderwidth=0, highlightthickness=0, bg=self.manager.colors["surface"])
        scrollbar = tk.Scrollbar(checklist_container, orient="vertical", command=canvas.yview)
        scrollable_frame = tk.Frame(canvas, bg=self.manager.colors["surface"])
        
        scrollable_frame.bind(
            "<Configure>",
            lambda e: canvas.configure(scrollregion=canvas.bbox("all"))
        )
        
        canvas.create_window((0, 0), window=scrollable_frame, anchor="nw")
        canvas.configure(yscrollcommand=scrollbar.set)
        
        canvas.pack(side="left", fill="both", expand=True)
        scrollbar.pack(side="right", fill="y")
        
        # Group models by category
        categories = {
            "🎬 Video Generation (LTX-Video)": [e for e in self.all_entries if e["workflow"].startswith("video")],
            "🎵 Music Generation (AceStep)": [e for e in self.all_entries if e["workflow"] == "music"],
            "🗣 Voice Generation (VibeVoice)": [e for e in self.all_entries if e["workflow"] == "voice"],
            "🖼 Image Generation (Z-Image)": [e for e in self.all_entries if e["workflow"] == "image"],
            "🤖 Agentic Chatbot LLM (Qwen3)": [e for e in self.all_entries if e["workflow"] == "chatbot"],
        }
        
        for category_name, entries in categories.items():
            if not entries:
                continue
                
            # Category Header
            cat_frame = tk.Frame(scrollable_frame, pady=8, bg=self.manager.colors["surface"])
            cat_frame.pack(fill=tk.X, anchor="w")
            
            cat_lbl = tk.Label(cat_frame, text=category_name, font=("Segoe UI", 10, "bold"), fg=self.manager.colors["text"])
            cat_lbl.pack(side=tk.LEFT)
            self.manager._style_label(cat_lbl, "body_strong", self.manager.colors["surface"])
            
            sep = tk.Frame(cat_frame, height=1, bg=self.manager.colors["border"])
            sep.pack(side=tk.LEFT, fill=tk.X, expand=True, padx=(10, 0), pady=4)
            
            # Category Rows
            for entry in entries:
                row = tk.Frame(scrollable_frame, padx=14, pady=4, bg=self.manager.colors["surface"])
                row.pack(fill=tk.X, anchor="w")
                
                entry_id = entry["id"]
                is_installed = entry["resolved_path"] is not None
                
                # Recommendation Check
                rec = self.manager._get_model_vram_recommendation(entry_id, self.vram_gb)
                
                # Checkbutton
                var = tk.BooleanVar()
                if is_installed:
                    var.set(False)
                else:
                    var.set(rec["pre_select"])
                    
                self.selection_vars[entry_id] = (var, entry)
                
                # Bind callback to update the size label dynamically
                var.trace_add("write", lambda *args: self._update_size_summary())
                
                cb_text = entry["label"]
                if is_installed:
                    cb_text += " (Already Installed)"
                    
                cb = tk.Checkbutton(
                    row, 
                    text=cb_text, 
                    variable=var, 
                    bg=self.manager.colors["surface"],
                    activebackground=self.manager.colors["surface"],
                    fg=self.manager.colors["text"] if not is_installed else "#777777",
                    selectcolor=self.manager.colors["surface"]
                )
                cb.pack(side=tk.LEFT)
                if is_installed:
                    cb.config(state=tk.DISABLED)
                    
                # Filename and size info
                size_text = ""
                if entry.get("size_bytes"):
                    size_text = f"[{self.manager._format_byte_count(entry['size_bytes'])}]"
                    
                info_lbl = tk.Label(row, text=f"  {entry['filename']} {size_text}", font=("Segoe UI", 8), fg="#777777")
                info_lbl.pack(side=tk.LEFT)
                self.manager._style_label(info_lbl, "muted", self.manager.colors["surface"])
                
                # Badge
                if not is_installed:
                    badge_lbl = tk.Label(
                        row, 
                        text=f"  {rec['badge']}  ", 
                        font=("Segoe UI", 8, "bold"), 
                        fg="white", 
                        bg=rec["color"],
                        padx=4,
                        pady=1
                    )
                    badge_lbl.pack(side=tk.RIGHT, padx=6)
        
        # Bind Mousewheel scroll
        def _on_mousewheel(event):
            canvas.yview_scroll(int(-1*(event.delta/120)), "units")
        canvas.bind_all("<MouseWheel>", _on_mousewheel)
        
        # Bottom controls and summary
        bottom_frame = tk.Frame(shell)
        bottom_frame.pack(fill=tk.X, pady=(6, 0))
        self.manager._style_panel(bottom_frame, self.manager.colors["bg"])
        
        self.summary_lbl = tk.Label(bottom_frame, text="Selected: 0.0 GB")
        self.summary_lbl.pack(side=tk.LEFT)
        self.manager._style_label(self.summary_lbl, "body_strong", self.manager.colors["bg"])
        
        # Action Buttons
        btn_frame = tk.Frame(bottom_frame)
        btn_frame.pack(side=tk.RIGHT)
        self.manager._style_panel(btn_frame, self.manager.colors["bg"])
        
        close_btn = tk.Button(btn_frame, text="Close", command=self.dialog.destroy)
        close_btn.pack(side=tk.RIGHT, padx=(8, 0))
        self.manager._style_button(close_btn, "secondary")
        
        self.download_btn = tk.Button(btn_frame, text="Download Selected", command=self._download_selected)
        self.download_btn.pack(side=tk.RIGHT, padx=(8, 0))
        self.manager._style_button(self.download_btn, "primary")
        
        deselect_btn = tk.Button(btn_frame, text="Clear All", command=self._deselect_all)
        deselect_btn.pack(side=tk.RIGHT, padx=(8, 0))
        self.manager._style_button(deselect_btn, "secondary")
        
        select_rec_btn = tk.Button(btn_frame, text="Select Recommended", command=self._select_recommended)
        select_rec_btn.pack(side=tk.RIGHT)
        self.manager._style_button(select_rec_btn, "secondary")
        
        self._update_size_summary()
        
        # Center the dialog
        self.dialog.update_idletasks()
        x = self.parent.winfo_x() + (self.parent.winfo_width() - self.dialog.winfo_width()) // 2
        y = self.parent.winfo_y() + (self.parent.winfo_height() - self.dialog.winfo_height()) // 2
        self.dialog.geometry(f"+{x}+{y}")

    def _update_size_summary(self):
        total_bytes = 0
        selected_count = 0
        for entry_id, (var, entry) in self.selection_vars.items():
            if var.get() and entry["resolved_path"] is None:
                total_bytes += entry.get("size_bytes", 0)
                selected_count += 1
                
        self.summary_lbl.config(text=f"Selected: {selected_count} models ({self.manager._format_byte_count(total_bytes)})")
        if selected_count > 0:
            self.download_btn.config(state=tk.NORMAL)
        else:
            self.download_btn.config(state=tk.DISABLED)

    def _select_recommended(self):
        for entry_id, (var, entry) in self.selection_vars.items():
            if entry["resolved_path"] is not None:
                var.set(False)
            else:
                rec = self.manager._get_model_vram_recommendation(entry_id, self.vram_gb)
                var.set(rec["pre_select"])

    def _deselect_all(self):
        for var, entry in self.selection_vars.values():
            var.set(False)

    def _download_selected(self):
        chosen_ids = []
        for entry_id, (var, entry) in self.selection_vars.items():
            if var.get() and entry["resolved_path"] is None:
                chosen_ids.append(entry_id)
                
        if not chosen_ids:
            return
            
        self.dialog.destroy()
        self.manager.install_missing_models(interactive=True, selected_manifest_ids=chosen_ids)


class SplashScreen:
    """Branded splash screen shown during startup while the main window loads."""

    _BG          = "#08111f"
    _BORDER      = "#223657"       # kept for internal use; outer border is now gradient
    _ACCENT      = "#00e5ff"       # neon turquoise (matches logo left-side glow)
    _MUTED       = "#99a8c7"
    _TEXT        = "#edf4ff"
    _BAR_TRACK   = "#223657"
    _BAR_FILL    = "#00e5ff"       # neon turquoise progress fill
    _GRAD_LEFT   = "#00e5ff"       # neon turquoise
    _GRAD_RIGHT  = "#c800ff"       # neon purple
    _BORDER_THICK = 5              # px — neon gradient border thickness
    _WIDTH     = 745
    _HEIGHT    = 850
    _LOGO_SIZE = 400
    _BAR_PADX  = 107

    # ── Startup timing constants ──────────────────────────────────────────
    _EMA_ALPHA         = 0.3
    _TIMING_STAGE_KEYS = ["s0_s1", "s1_s2", "s2_s3", "s3_s4", "s4_s5", "s5_s6", "s6_done"]
    # progress checkpoint value -> index of the stage that just completed
    _PROGRESS_CHECKPOINTS = {0.05: 0, 0.20: 1, 0.35: 2, 0.55: 3, 0.72: 4, 0.88: 5, 1.0: 6}

    def __init__(self, root):
        self._root = root
        self._photo = None

        # ── Load startup timing data ──────────────────────────────────────
        _lad = os.environ.get("LOCALAPPDATA") or os.environ.get("APPDATA") or ""
        self._timing_file = os.path.join(_lad, APP_NAME, "startup_timing.json") if _lad else ""
        self._ema = {}
        self._run_count = 0
        if self._timing_file and os.path.exists(self._timing_file):
            try:
                with open(self._timing_file, "r", encoding="utf-8") as _tf:
                    _td = json.load(_tf)
                self._ema = {
                    k: float(v) for k, v in _td.get("ema", {}).items()
                    if k in self._TIMING_STAGE_KEYS
                    and isinstance(v, (int, float)) and v > 0
                }
                self._run_count = int(_td.get("run_count", 0))
            except Exception:
                self._ema = {}
                self._run_count = 0

        # Timing state for this run
        self._t_start       = time.perf_counter()
        self._t_stage_start = self._t_start
        self._stage_times   = {}
        self._completed     = False
        self._eta_ticker_id = None
        self._eta_deadline  = 0.0  # absolute perf_counter deadline; 0 = not yet set
        # ── Smooth bar interpolation state ─────────────────────────────────
        self._interp_from      = 0.0   # bar value when last ETA was computed
        self._interp_eta_start = 0.0   # perf_counter when interpolation began
        self._interp_eta_total = 0.0   # total seconds to interpolate over (0 = disabled)

        sw = root.winfo_screenwidth()
        sh = root.winfo_screenheight()
        x = (sw - self._WIDTH) // 2
        y = (sh - self._HEIGHT) // 2

        self._top = tk.Toplevel(root)
        self._top.overrideredirect(True)
        self._top.attributes("-topmost", True)
        self._top.geometry(f"{self._WIDTH}x{self._HEIGHT}+{x}+{y}")
        self._top.configure(bg=self._BG, highlightthickness=0)

        # ── Neon gradient border canvas (behind everything, always visible) ─
        # A plain Canvas covering the full window is placed FIRST (behind).
        # A content frame placed on top of it with T-px inset on all sides
        # exposes the border canvas edges — no z-order fighting needed.
        T = self._BORDER_THICK
        self._border_canvas = tk.Canvas(
            self._top, bg=self._BG, bd=0, highlightthickness=0,
            width=self._WIDTH, height=self._HEIGHT)
        self._border_canvas.place(x=0, y=0)
        _draw_neon_rounded_border(
            self._border_canvas, self._WIDTH, self._HEIGHT,
            thickness=T, radius=14, bg=self._BG)

        # ── Inner content frame (inset by T px on all sides) ───────────────
        _cw = self._WIDTH  - 2 * T
        _ch = self._HEIGHT - 2 * T
        self._content = tk.Frame(self._top, bg=self._BG, bd=0, highlightthickness=0)
        self._content.place(x=T, y=T, width=_cw, height=_ch)

        # ── Logo (ICO → PIL image, _LOGO_SIZE×_LOGO_SIZE) ──────────────────
        logo_loaded = False
        try:
            from PIL import Image as _PImage, ImageTk as _PImageTk
            resource_root = getattr(sys, "_MEIPASS", os.path.dirname(os.path.abspath(__file__)))
            ico_path = os.path.join(resource_root, "Prompt2MTV.ico")
            if os.path.exists(ico_path):
                img = _PImage.open(ico_path)
                # ICO may have multiple sizes; pick the largest
                sizes = getattr(img, "n_frames", 1)
                best = img
                if sizes > 1:
                    best_size = 0
                    for i in range(sizes):
                        img.seek(i)
                        w, h = img.size
                        if w > best_size:
                            best_size = w
                            best = img.copy()
                best = best.convert("RGBA").resize(
                    (self._LOGO_SIZE, self._LOGO_SIZE), _PImage.LANCZOS)
                self._photo = _PImageTk.PhotoImage(best)
                tk.Label(self._content, image=self._photo,
                         bg=self._BG, bd=0).pack(pady=(28, 0))
                logo_loaded = True
        except Exception:
            pass

        if not logo_loaded:
            tk.Label(self._content, text="\U0001f3ac", font=("Segoe UI Emoji", 160),
                     bg=self._BG, fg=self._ACCENT).pack(pady=(28, 0))

        # ── App name ───────────────────────────────────────────────────────
        tk.Label(self._content,
                 text=APP_NAME,
                 font=("Segoe UI Semibold", 36),
                 bg=self._BG, fg=self._ACCENT).pack(pady=(20, 0))

        # ── Version ────────────────────────────────────────────────────────
        tk.Label(self._content,
                 text=f"v{APP_VERSION}",
                 font=("Segoe UI", 13),
                 bg=self._BG, fg=self._ACCENT).pack(pady=(2, 0))

        # ── Tagline ────────────────────────────────────────────────────────
        tk.Label(self._content,
                 text=APP_TAGLINE,
                 font=("Segoe UI", 16),
                 bg=self._BG, fg=self._MUTED).pack(pady=(8, 0))

        # ── Author ─────────────────────────────────────────────────────────
        tk.Label(self._content,
                 text="By Rorri Maesu",
                 font=("Segoe UI", 13),
                 bg=self._BG, fg=self._MUTED).pack(pady=(4, 0))

        # ── Buy Me a Coffee link ───────────────────────────────────────────
        _coffee_lbl = tk.Label(self._content,
                               text="☕  buymeacoffee.com/rorrimaesu",
                               font=("Segoe UI", 11),
                               bg=self._BG, fg=self._MUTED,
                               cursor="hand2")
        _coffee_lbl.pack(pady=(6, 0))
        _coffee_lbl.bind("<Button-1>", lambda _e: webbrowser.open(BUYMEACOFFEE_URL))
        _coffee_lbl.bind("<Enter>",   lambda _e: _coffee_lbl.config(fg=self._ACCENT))
        _coffee_lbl.bind("<Leave>",   lambda _e: _coffee_lbl.config(fg=self._MUTED))

        # ── Progress bar canvas ────────────────────────────────────────────
        bar_frame = tk.Frame(self._content, bg=self._BG)
        bar_frame.pack(fill=tk.X, padx=self._BAR_PADX, pady=(20, 0))

        self._bar_w = _cw - self._BAR_PADX * 2
        self._bar_h = 12
        self._bar_canvas = tk.Canvas(bar_frame,
                                     width=self._bar_w, height=self._bar_h,
                                     bg=self._BG, bd=0, highlightthickness=0)
        self._bar_canvas.pack()

        # Track rectangle (background)
        self._bar_canvas.create_rectangle(0, 0, self._bar_w, self._bar_h,
                                          fill=self._BAR_TRACK, outline="",
                                          tags="track")
        # Gradient fill — N vertical strips from turquoise (#00e5ff) → purple (#c800ff)
        _N = 80
        _lr, _lg, _lb = 0x00, 0xe5, 0xff   # turquoise
        _rr, _rg, _rb = 0xc8, 0x00, 0xff   # purple
        for _i in range(_N):
            _t  = _i / (_N - 1)
            _cr = int(_lr + (_rr - _lr) * _t)
            _cg = int(_lg + (_rg - _lg) * _t)
            _cb = int(_lb + (_rb - _lb) * _t)
            _x0 = int(self._bar_w * _i / _N)
            _x1 = int(self._bar_w * (_i + 1) / _N)
            self._bar_canvas.create_rectangle(
                _x0, 0, _x1, self._bar_h,
                fill=f"#{_cr:02x}{_cg:02x}{_cb:02x}", outline="",
                tags="grad_fill")
        # Mask rectangle: covers gradient from fill_w rightward (shrinks left as bar fills)
        self._mask_id = self._bar_canvas.create_rectangle(
            0, 0, self._bar_w, self._bar_h,
            fill=self._BAR_TRACK, outline="", tags="mask")

        # ── Status label (fixed-height zone so text never clips) ──────────
        status_zone = tk.Frame(self._content, bg=self._BG, height=54)
        status_zone.pack(fill=tk.X, pady=(16, 4))
        status_zone.pack_propagate(False)
        self._status_var = tk.StringVar(value="Starting up\u2026")
        self._status_lbl = tk.Label(status_zone,
                                    textvariable=self._status_var,
                                    font=("Segoe UI", 13),
                                    bg=self._BG, fg=self._MUTED,
                                    wraplength=_cw - 40,
                                    justify=tk.CENTER)
        self._status_lbl.pack(expand=True)

        # ── ETA label (fixed-height; blank until run 2+) ──────────────────
        eta_zone = tk.Frame(self._content, bg=self._BG, height=24)
        eta_zone.pack(fill=tk.X, pady=(0, 14))
        eta_zone.pack_propagate(False)
        self._eta_var = tk.StringVar(value="")
        self._eta_lbl = tk.Label(eta_zone,
                                 textvariable=self._eta_var,
                                 font=("Segoe UI", 10),
                                 bg=self._BG, fg=self._MUTED,
                                 justify=tk.CENTER)
        self._eta_lbl.pack(expand=True)

        # Force an immediate paint so the window renders before __init__ blocks
        self._top.update()

    def _set_bar_value(self, value: float):
        """Reveal the gradient bar up to `value` (0.0–1.0) by moving the mask."""
        fill_w = max(0, min(int(self._bar_w * value), self._bar_w))
        self._bar_canvas.coords(self._mask_id, fill_w, 0, self._bar_w, self._bar_h)

    def set_progress(self, value: float, status: str = ""):
        """Update the progress bar (0.0–1.0), status text, and ETA."""
        if not self._top.winfo_exists():
            return
        self._set_bar_value(value)
        if status:
            self._status_var.set(status)

        # ── Per-stage timing & adaptive ETA ───────────────────────────────
        now = time.perf_counter()
        stage_idx = self._PROGRESS_CHECKPOINTS.get(value)
        if stage_idx is not None:
            self._stage_times[self._TIMING_STAGE_KEYS[stage_idx]] = now - self._t_stage_start
            if value >= 1.0:
                self._completed = True
            if self._run_count > 0 and self._ema:
                done_keys       = self._TIMING_STAGE_KEYS[:stage_idx + 1]
                pending_keys    = self._TIMING_STAGE_KEYS[stage_idx + 1:]
                expected_so_far = sum(self._ema.get(k, 0.0) for k in done_keys)
                if expected_so_far > 0 and pending_keys:
                    speed_ratio      = max(0.3, min(3.0, (now - self._t_start) / expected_so_far))
                    eta_secs         = speed_ratio * sum(self._ema.get(k, 0.0) for k in pending_keys)
                    self._eta_deadline    = now + eta_secs
                    # Seed smooth interpolation from current milestone forward to 1.0
                    self._interp_from      = value
                    self._interp_eta_start = now
                    self._interp_eta_total = eta_secs
                    self._update_eta_label(eta_secs)
                    if self._eta_ticker_id is not None:
                        try:
                            self._top.after_cancel(self._eta_ticker_id)
                        except Exception:
                            pass
                    self._eta_ticker_id = self._top.after(200, self._tick_eta)
                elif not pending_keys:
                    # Final checkpoint — show "Almost ready…" instead of going blank
                    self._interp_eta_total = 0.0
                    self._update_eta_label(0.0)
                else:
                    self._eta_var.set("")
            self._t_stage_start = now

        self._top.update_idletasks()

    def _update_eta_label(self, secs: float):
        """Format and display the ETA value."""
        if self._run_count == 0:
            self._eta_var.set("")
            return
        if secs < 1.5:
            self._eta_var.set("Almost ready\u2026")
        elif secs < 60:
            self._eta_var.set(f"~{int(secs)}s remaining")
        else:
            mins, rem = divmod(int(secs), 60)
            self._eta_var.set(f"~{mins}m {rem}s remaining")

    def _tick_eta(self):
        """Live countdown — fires every 200 ms, updates ETA label and animates bar."""
        try:
            if not self._top.winfo_exists():
                return
        except Exception:
            return
        now = time.perf_counter()
        remaining = max(0.0, self._eta_deadline - now)
        self._update_eta_label(remaining)
        # Smooth bar: interpolate from last milestone value → 1.0 over the ETA duration
        if self._interp_eta_total > 0:
            frac = min(1.0, (now - self._interp_eta_start) / self._interp_eta_total)
            smooth_val = self._interp_from + (1.0 - self._interp_from) * frac
            self._set_bar_value(smooth_val)
        self._eta_ticker_id = self._top.after(200, self._tick_eta)

    def tick(self):
        """Explicit pump for long-running blocking phases (e.g. deferred tab builds).
        Refreshes the ETA label and flushes pending Tkinter events."""
        try:
            if not self._top.winfo_exists():
                return
        except Exception:
            return
        if self._eta_deadline > 0:
            remaining = max(0.0, self._eta_deadline - time.perf_counter())
            self._update_eta_label(remaining)
        self._top.update_idletasks()

    def close(self):
        """Persist timing EMA and destroy the splash window."""
        # Cancel live ticker
        if self._eta_ticker_id is not None:
            try:
                self._top.after_cancel(self._eta_ticker_id)
            except Exception:
                pass
            self._eta_ticker_id = None

        # Update EMA and write to disk when startup completed normally
        if self._completed and self._timing_file:
            try:
                for key, actual in self._stage_times.items():
                    if key in self._ema:
                        self._ema[key] = self._EMA_ALPHA * actual + (1.0 - self._EMA_ALPHA) * self._ema[key]
                    else:
                        self._ema[key] = actual  # seed on first ever run
                self._run_count += 1
                payload = {
                    "app_version": APP_VERSION,
                    "run_count":   self._run_count,
                    "ema":         {k: round(v, 4) for k, v in self._ema.items()},
                }
                os.makedirs(os.path.dirname(self._timing_file), exist_ok=True)
                tmp = self._timing_file + ".tmp"
                with open(tmp, "w", encoding="utf-8") as _f:
                    json.dump(payload, _f, indent=2)
                os.replace(tmp, self._timing_file)
            except Exception:
                pass

        try:
            if self._top.winfo_exists():
                self._top.destroy()
        except Exception:
            pass


