        dest_lbl.pack(side=tk.LEFT)
        self._style_label(dest_lbl, "body", self.colors["bg"])

        default_root = "D:\\" if os.path.exists("D:\\") else "C:\\"
        default_dest = os.path.join(default_root, "ComfyUI_Portable")
        
